WITH flattened AS (SELECT id, plan, effective_from, element FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) t AS element) SELECT plan, CASE WHEN element >= 67 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, MIN(element) AS min_element, COUNT(DISTINCT id) AS distinct_ids, ROUND(SUM(element) / NULLIF(COUNT(CASE WHEN plan = 'basic' THEN 1 END), 0), 2) AS element_per_basic, GROUPING_ID() AS grouping_level FROM flattened GROUP BY GROUPING SETS ((plan, CASE WHEN element >= 67 THEN 'PREMIUM' ELSE 'STANDARD' END), (plan));
